using System.Collections.Generic;using System.Text;public class Solution{public IList<string> FullJustify(string[]w,int W){var o=new List<string>();for(int i=0;i<w.Length;){int j=i,len=0;while(j<w.Length&&len+w[j].Length+j-i<=W)len+=w[j++].Length;int gaps=j-i-1;var l=new StringBuilder();if(j==w.Length||gaps==0){for(int k=i;k<j;k++){if(k>i)l.Append(' ');l.Append(w[k]);}while(l.Length<W)l.Append(' ');}else{int s=W-len,b=s/gaps,e=s%gaps;for(int k=i;k<j;k++){l.Append(w[k]);if(k<j-1)l.Append(' ',b+(k-i<e?1:0));}}o.Add(l.ToString());i=j;}return o;}}
